fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    // Collect the chars into a vector for indexing
    let chars: Vec<char> = txt.chars().collect();

    if chars.is_empty() {
        return false;
    }

    let last_char = chars[chars.len() - 1];
    let is_ascii_alpha = ('A' <= last_char && last_char <= 'Z') || ('a' <= last_char && last_char <= 'z');

    if !is_ascii_alpha {
        return false;
    }

    if chars.len() == 1 {
        true
    } else {
        chars[chars.len() - 2] == ' '
    }
}